mapper.sql:
WHERE p.status = 'WAIT_LABEL' AND m.status = 1
  AND NOT EXISTS (SELECT 1 FROM ecom_owh_outbound x WHERE x.package_id = p.id AND x.status IN ('PUSHED', 'INTERCEPTING', 'OUTBOUND', 'SHIPPED'))
AND m.account_id = #{accountId}
AND p.warehouse_id = #{warehouseId}
AND p.store_id = #{storeId}

    AND (p.package_no LIKE CONCAT('%', #{keyword}, '%') OR p.ship_name LIKE CONCAT('%', #{keyword}, '%')
         OR EXISTS (SELECT 1 FROM ecom_package_item pi JOIN ecom_order eo ON eo.id = pi.order_id
                    WHERE pi.package_id = p.id AND eo.platform_order_no LIKE CONCAT('%', #{keyword}, '%')))

